553	  final bool hasMore;
554	  final bool isLoading;
555	  final bool failed;
556	  final VoidCallback onRetry;
557	
558	  @override
559	  Widget build(BuildContext context) {
560	    if (failed) {
561	      return Padding(
562	        padding: const EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
563	        child: Center(
564	          child: TextButton(
565	            onPressed: onRetry,
566	            child: Text(
567	              'Tentar novamente',
568	              style: DesignTokens.textLabelMd.copyWith(
569	                color: DesignTokens.colorPrimary,
570	              ),
571	            ),
572	          ),
573	        ),
574	      );
575	    }
576	    if (isLoading) {
577	      return const Padding(
578	        padding: EdgeInsets.symmetric(vertical: DesignTokens.spacingMd),
579	        child: Center(
580	          child: CircularProgressIndicator(color: DesignTokens.colorPrimary),
581	        ),
582	      );
583	    }
584	    return const SizedBox.shrink();
585	  }
586	}
587	
588	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
589	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
590	/// always already truncated to local midnight (`EntryDateGroup`'s own
591	/// contract).
592	String _dayLabel(DateTime date) {
593	  final now = DateTime.now();
594	  final today = DateTime(now.year, now.month, now.day);
595	  final yesterday = today.subtract(const Duration(days: 1));
596	  if (date == today) {
597	    return 'Hoje';
598	  }
599	  if (date == yesterday) {
600	    return 'Ontem';
601	  }
602	  final day = date.day.toString().padLeft(2, '0');
603	  final month = date.month.toString().padLeft(2, '0');
604	  return '$day/$month/${date.year}';
605	}
