  // never arm for an in-flight search resumed this way.
  if (widget.searchCubit.state is ResourceLoading<List<Entry>>) {
    _searchSkeletonTimer = Timer(_skeletonThreshold, () {
      if (mounted) {
        setState(() => _showSearchSkeleton = true);
      }
    });
  }
}

